-- 0356 — the cultures arrive: the empty family, filled by a rule.
--
-- **The owner's direction, 2026-08-25: the `culture:` family has had a wire
-- slot, a mint convention (0337) and an assertion surface since it was
-- designed, and zero members.** One curated CC0 source fills it the way the
-- eight genre layers were filled: countries (P31/P279* Q6256), dependent
-- territories (Q161243) and constituent countries (Q1763527), undissolved —
-- a fallen empire is a history subject, not a living cultural sphere. The
-- owner's definition is binding here: a culture is the country as a cultural
-- sphere, **not the place as a location** — which is why the fetch guard's
-- place-contradiction is waived for exactly this slice and no other.
--
-- **The walk alone leaks, and the fence is an identity property.** Measured
-- on the first fetch: `municipality of Portugal`, `Roman province` and
-- `micronation` all chain P279* to country, so Tavira, Cisalpine Gaul and
-- the Republic of Molossia arrived as cultures. The fence — an ISO 3166-1
-- code, a literal `P31 country`, or the constituent-country arm — removed
-- every leaker and kept Scotland, Wales, Hong Kong, Taiwan and Kosovo. Two
-- label rules were learned on the same fetch and live in
-- `tools/wikidata_vocab.py`: the official short name (P1813, read through
-- statement nodes because truthy serving hid "China"@en behind a preferred-
-- rank 中国) is the name people say, so Q148 is `culture:china` rather than
-- its formal label; and a whole and its part sharing a name is the source's
-- formal/common split, not ambiguity — the Kingdom of the Netherlands cedes
-- `netherlands` to the constituent it P150-contains.
--
-- **The twin-merge is narrowed to `place` twins, and that is the decision of
-- record.** `place:hong_kong`, `place:italy` and `place:singapore` are the
-- same referents held as locations — unparented, no origin, never used as
-- headings — so a culture import re-keys onto its place twin, which learns
-- its names and gains the `medium:cultures` parent. A twin of any *other*
-- kind refuses the merge and the import mints beside it, keeping whatever
-- labels do not collide: the user-kept work "Japan" (genre:pop) holds the
-- label `japan`, so `culture:japan` arrives **without its English name** —
-- asserted below as a measured conflict for owner adjudication, because an
-- import that quietly captured a user's kept term, or a culture silently
-- folded onto somebody's song, would each be worse than the gap.
--
-- 255 concepts, all under `medium:cultures` beneath `hub:places_cultures` —
-- the node first, because 0348's discipline is that nothing hangs from a
-- bare layered hub.

begin;

create temporary table wikidata_payload (data jsonb) on commit drop;
insert into wikidata_payload values ($json$[{"k":"culture:france","kind":"culture","l":"France","d":"country in Western Europe and other continents (through its overseas territories in America, Africa and Oceania)","labels":[["France","france","en","preferred"],["French Republic","french republic","en","alternate"],["フランス","フランス","ja","alternate"],["法朗西","法朗西","ja","alternate"],["フランス共和国","フランス共和国","ja","alternate"],["仏蘭西","仏蘭西","ja","alternate"]],"parent":"medium:cultures","qid":"Q142","sitelinks":428,"slice":"cultures"},{"k":"culture:america","kind":"culture","l":"America","d":"country located primarily in North America","labels":[["America","america","en","preferred"],["United States","united states","en","alternate"],["the States","the states","en","alternate"],["the United States of America","the united states of america","en","alternate"],["US of America","us of america","en","alternate"],["the US","the us","en","alternate"]],"parent":"medium:cultures","qid":"Q30","sitelinks":426,"slice":"cultures"},{"k":"culture:turkey","kind":"culture","l":"Turkey","d":"country in West Asia and Southeast Europe","labels":[["Turkey","turkey","en","preferred"],["Republic of Türkiye","republic of türkiye","en","alternate"],["Republic of Turkey","republic of turkey","en","alternate"],["トルコ","トルコ","ja","alternate"],["トルコ共和国","トルコ共和国","ja","alternate"],["テュルキエ","テュルキエ","ja","alternate"]],"parent":"medium:cultures","qid":"Q43","sitelinks":425,"slice":"cultures"},{"k":"culture:russia","kind":"culture","l":"Russia","d":"country in Eastern Europe and Northern Asia, the largest in the world by area","labels":[["Russia","russia","en","preferred"],["Russian Federation","russian federation","en","alternate"],["RUS","rus","en","alternate"],["ロシア","ロシア","ja","alternate"],["ロシア連邦","ロシア連邦","ja","alternate"],["러시아","러시아","ko","alternate"]],"parent":"medium:cultures","qid":"Q159","sitelinks":421,"slice":"cultures"},{"k":"culture:japan","kind":"culture","l":"Japan","d":"island country in East As