itelinks":154,"slice":"cultures"},{"k":"culture:christmas_island","kind":"culture","l":"Christmas Island","d":"island and external territory of Australia, located in the Indian Ocean","labels":[["Christmas Island","christmas island","en","preferred"],["Christmas Island, Other Territories","christmas island other territories","en","alternate"],["Christmas Island, Other Territories, Australia","christmas island other territories australia","en","alternate"],["Territory of Christmas Island","territory of christmas island","en","alternate"],["クリスマス島","クリスマス島","ja","alternate"],["CXR","cxr","ja","alternate"]],"parent":"medium:cultures","qid":"Q31063","sitelinks":153,"slice":"cultures"},{"k":"culture:wallis_and_futuna","kind":"culture","l":"Wallis and Futuna","d":"overseas collectivity of France","labels":[["Wallis and Futuna","wallis and futuna","en","preferred"],["Wallis and Futuna Islands","wallis and futuna islands","en","alternate"],["Wallis & Futuna","wallis futuna","en","alternate"],["ウォリス・フツナ","ウォリス フツナ","ja","alternate"],["ワリス・フテュナ諸島","ワリス フテュナ諸島","ja","alternate"],["ウォリス・フツナ諸島","ウォリス フツナ諸島","ja","alternate"]],"parent":"medium:cultures","qid":"Q35555","sitelinks":147,"slice":"cultures"},{"k":"culture:norfolk_island","kind":"culture","l":"Norfolk Island","d":"external territory of Australia in the South Pacific Ocean, consisting of the island of the same name plus neighbouring islands","labels":[["Norfolk Island","norfolk island","en","preferred"],["Norfolk Island, Other Territories, Australia","norfolk island other territories australia","en","alternate"],["Norfolk Island, Other Territories","norfolk island other territories","en","alternate"],["Territory of Norfolk Island","territory of norfolk island","en","alternate"],["Norfolk Island, Australia","norfolk island australia","en","alternate"],["ノーフォーク島","ノーフォーク島","ja","alternate"]],"parent":"medium:cultures","qid":"Q31057","sitelinks":144,"slice":"cultures"},{"k":"culture:saint_pierre_and_miquelon","kind":"cultu