"qid":"Q126125","sitelinks":102,"slice":"cultures"},{"k":"culture:bouvet_island","kind":"culture","l":"Bouvet Island","d":"Norwegian uninhabited subantarctic volcanic island","labels":[["Bouvet Island","bouvet island","en","preferred"],["ブーベ島","ブーベ島","ja","alternate"],["ブーヴェ島","ブーヴェ島","ja","alternate"],["부베섬","부베섬","ko","alternate"],["布韦岛","布韦岛","zh","alternate"]],"parent":"medium:cultures","qid":"Q23408","sitelinks":102,"slice":"cultures"},{"k":"culture:heard_island_and_mcdonald_islands","kind":"culture","l":"Heard Island and McDonald Islands","d":"Australian external territory and volcanic group of barren Antarctic islands","labels":[["Heard Island and McDonald Islands","heard island and mcdonald islands","en","preferred"],["Territory of Heard Island and McDonald Islands","territory of heard island and mcdonald islands","en","alternate"],["Heard and McDonald Islands","heard and mcdonald islands","en","alternate"],["HIMI","himi","en","alternate"],["Heard and Macdonald Islands","heard and macdonald islands","en","alternate"],["HMD","hmd","en","alternate"]],"parent":"medium:cultures","qid":"Q131198","sitelinks":97,"slice":"cultures"},{"k":"culture:french_southern_and_antarctic_lands","kind":"culture","l":"French Southern and Antarctic Lands","d":"overseas territory of France","labels":[["French Southern and Antarctic Lands","french southern and antarctic lands","en","preferred"],["French Southern Territories","french southern territories","en","alternate"],["フランス領南方・南極地域","フランス領南方 南極地域","ja","alternate"],["仏領南方地域","仏領南方地域","ja","alternate"],["フランス領極南諸島","フランス領極南諸島","ja","alternate"],["フランス領南方地域","フランス領南方地域","ja","alternate"]],"parent":"medium:cultures","qid":"Q129003","sitelinks":93,"slice":"cultures"},{"k":"culture:clipperton_island","kind":"culture","l":"Clipperton Island","d":"French atoll in the Pacific Ocean","labels":[["Clipperton Island","clipperton island","en","preferred"],["Passion Island","passion island","en","alternate"],["La Passion–Clipperton","la pass